pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address payable lender, address borrower, uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration, bool repayDirect, bool isCallback) public {
        // Bound inputs to reasonable values
        amount = bound(amount, 1, 1e30);
        interest = bound(interest, 1, 1e18);
        loanToCollateral = bound(loanToCollateral, 1, 1e30);
        duration = bound(duration, 1, 365 days);
        vm.assume(lender != address(0) && borrower != address(0) && lender != borrower);
        vm.assume(lender != address(c) && borrower != address(c));

        // Setup: give borrower enough collateral
        vm.deal(borrower, 1e30);
        vm.deal(lender, 1e30);

        // Create a loan request
        vm.prank(borrower);
        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration);

        // Clear the request (lender provides debt tokens)
        vm.prank(lender);
        uint256 loanID = c.clearRequest(reqID, repayDirect, isCallback);

        // Approve transfer to a new owner
        address newOwner = address(0x1234);
        vm.prank(lender);
        c.approveTransfer(newOwner, loanID);

        // Transfer ownership
        vm.prank(newOwner);
        c.transferOwnership(loanID);

        // Check: the lender of the loan should now be newOwner
        (,,,,, address currentLender,,) = c.getLoan(loanID);
        assertTrue(currentLender == newOwner);
    }
}

