pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address lender, address newLender, address other) public {
        vm.assume(lender != address(0) && lender != address(c));
        vm.assume(newLender != address(0) && newLender != address(c));
        vm.assume(other != address(0) && other != address(c));
        vm.assume(lender != newLender && lender != other && newLender != other);

        address owner = address(uint160(uint256(keccak256(abi.encodePacked(lender, block.number)))));
        vm.assume(owner != address(0) && owner != address(c));

        uint256 amount = bound(uint256(uint160(lender)), 1, 100 ether);
        uint256 interest = bound(uint256(uint160(newLender)), 1, 1000);
        uint256 ltc = bound(uint256(uint160(other)), 1, 1000);
        uint256 duration = bound(uint256(uint160(lender)) ^ uint256(uint160(newLender)), 1 days, 365 days);

        vm.deal(owner, 100 ether);
        vm.deal(lender, 100 ether);
        vm.deal(newLender, 100 ether);
        vm.deal(other, 100 ether);

        vm.startPrank(owner);
        uint256 reqId = c.requestLoan(amount, interest, ltc, duration);
        vm.stopPrank();

        vm.startPrank(lender);
        c.clearRequest(reqId, false, false);
        vm.stopPrank();

        uint256 loanId = 0;

        vm.prank(lender);
        c.approveTransfer(newLender, loanId);

        vm.prank(newLender);
        c.transferOwnership(loanId);

        C.Loan memory loan = c.getLoan(loanId);
        assertTrue(loan.lender == newLender, "Lender should be the caller of transferOwnership");
    }
}

