        // Request loan from owner
        vm.prank(owner);
        vm.assume(address(collateralToken) != address(0));

        // The rule: approveTransfer must work with the debt token
        // If debt() returns wrong token, transferFrom in clearRequest will fail
        // We test this by attempting a clearRequest and checking if it reverts

        // Setup: owner requests a loan
